package com.flymaccin.demonicaistudio;
import android.app.*;import android.graphics.Color;import android.view.*;import android.widget.*;
public final class FmeGamesRoom{private FmeGamesRoom(){}public static View build(Activity a){LinearLayout l=new LinearLayout(a);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(20,18,20,18);l.setBackgroundColor(Color.rgb(7,7,15));TextView h=new TextView(a);h.setText("FME GAMES ARCADE");h.setTextSize(28);h.setTextColor(Color.WHITE);l.addView(h);TextView s=new TextView(a);s.setText("Choose a native room. Games run inside Demonic Fun Hub.");s.setTextColor(Color.LTGRAY);l.addView(s);FrameLayout stage=new FrameLayout(a);l.addView(stage,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(a);String[][] games={{"8-BIT ISM","8bit"},{"HY-PHYXELS","hyphyxels"},{"BAY CARNIVAL3","carnival"}};for(String[]g:games){Button x=new Button(a);x.setText(g[0]);x.setOnClickListener(v->{stage.removeAllViews();stage.addView(GameRooms.build(a,g[1]),new FrameLayout.LayoutParams(-1,-1));});nav.addView(x);}l.addView(nav);stage.addView(GameRooms.build(a,"hyphyxels"),new FrameLayout.LayoutParams(-1,-1));return l;}}
